  const parse = (v) => {
    const [core, pre] = v.split('-');
    const [major, minor, patch] = core.split('.');
    return {
      major: parseInt(major, 10),
      minor: parseInt(minor, 10),
      patch: parseInt(patch, 10),
      pre: pre ? pre.split('.').map((p, i) => ({
        numeric: i === 0 ? parseInt(p, 10) : null,
        label: p.toLowerCase()
      })) : null,
      core
    };
  };

  const x = parse(a), y = parse(b);

  if (x.major !== y.major) return x.major - y.major;
  if (x.minor !== y.minor) return x.minor - y.minor;
  if (x.patch !== y.patch) return x.patch - y.patch;

  // If both have no pre-release, they are equal
  if (x.pre === null && y.pre === null) return 0;

  // If one has pre-release and the other doesn't, the one without is greater
  if (x.pre === null) return 1;
  if (y.pre === null) return -1;

  // Compare pre-release identifiers
  const p = x.pre, q = y.pre;
  for (let i = 0; i < Math.max(p.length, q.length); i++) {
    const a = p[i], b = q[i];
    // Both have numeric identifiers: compare as numbers
    if (a.numeric !== null && b.numeric !== null) {
      if (a.numeric !== b.numeric) return a.numeric - b.numeric;
    }
    // If one is numeric and the other is a label, numeric is less (alpha < beta)
    else if (a.numeric !== null && b.numeric === null) return -1;
    else if (a.numeric === null && b.numeric !== null) return 1;
    // Both are labels: compare alphabetically
    else {
      const cmp = a.label.localeCompare(b.label);
      if (cmp !== 0) return cmp;
    }
  }

  // If pre-releases are equal, the one without pre-release is greater
  return 0;
}
