  let i = 0;

  function skipSpaces() {
    while (i < expr.length && expr[i] === ' ') i++;
  }

  function parseExpr() {
    let val = parseTerm();
    while (true) {
      skipSpaces();
      if (i < expr.length && expr[i] === '+') { i++; val += parseTerm(); }
      else if (i < expr.length && expr[i] === '-') { i++; val -= parseTerm(); }
      else break;
    }
    return val;
  }

  function parseTerm() {
    let val = parseFactor();
    while (true) {
      skipSpaces();
      if (i < expr.length && expr[i] === '*') { i++; val *= parseFactor(); }
      else if (i < expr.length && expr[i] === '/') { i++; val /= parseFactor(); }
      else break;
    }
    return val;
  }

  function parseFactor() {
    skipSpaces();
    if (i < expr.length && expr[i] === '(') {
      i++;
      let val = parseExpr();
      skipSpaces();
      if (i < expr.length && expr[i] === ')') i++;
      return val;
    }
    return parseUnary();
  }

  function parseUnary() {
    skipSpaces();
    if (i < expr.length && expr[i] === '-') {
      i++;
      return -parseFactor();
    }
    return parseNumber();
  }

  function parseNumber() {
    skipSpaces();
    let start = i;
    while (i < expr.length && /[\d.]/.test(expr[i])) i++;
    return parseFloat(expr.slice(start, i));
  }

  return parseExpr();
}
