    const aTokens = a.match(/(\d+)|([^0-9]+)/g) || [];
    const bTokens = b.match(/(\d+)|([^0-9]+)/g) || [];

    for (let i = 0; i < Math.min(aTokens.length, bTokens.length); i++) {
      const ta = aTokens[i];
      const tb = bTokens[i];
      const aIsNum = /^\d+$/.test(ta);
      const bIsNum = /^\d+$/.test(tb);

      if (aIsNum && bIsNum) {
        const nA = parseInt(ta, 10);
        const nB = parseInt(tb, 10);
        if (nA !== nB) return nA - nB;
      } else if (aIsNum) {
        return -1;
      } else if (bIsNum) {
        return 1;
      } else {
        if (ta < tb) return -1;
        if (ta > tb) return 1;
      }
    }

    return aTokens.length - bTokens.length;
  });
}
