function solve(precos) {
  const n = precos.length;
  if (n <= 1) return 0;

  // Forward: max profit with at most 1 transaction up to day i
  const forward = new Array(n);
  let min = precos[0];
  for (let i = 0; i < n; i++) {
    min = Math.min(min, precos[i]);
    forward[i] = Math.max(i === 0 ? 0 : forward[i - 1], precos[i] - min);
  }

  // Backward: max profit with at most 1 transaction from day i to end
  const backward = new Array(n);
  let max = precos[n - 1];
  for (let i = n - 1; i >= 0; i--) {
    max = Math.max(max, precos[i]);
    backward[i] = Math.max(i === n - 1 ? 0 : backward[i + 1], max - precos[i]);
  }

  // Combine: best at most 2 transactions
  let maxProfit = forward[n - 1]; // 0 transactions
  for (let i = 0; i < n - 1; i++) {
    maxProfit = Math.max(maxProfit, forward[i] + backward[i + 1]);
  }

  return maxProfit;
}
